  text(ctx, 'ДО', 0, 190, { size: 190, font: FONT_T, weight: 400, color: '#fff', stroke: '#000', strokeW: 28 });
  text(ctx, 'GTA 6', 0, 420, { size: 270, font: FONT_T, weight: 400, color: C.yellow, stroke: '#000', strokeW: 38 });
  ctx.restore();
  ctx.save(); ctx.translate(620, 985); ctx.rotate(-0.06); fillRR(ctx, -260, -60, 520, 120, 18, C.red); text(ctx, 'НЕТ ДЕНЕГ', 0, 4, { size: 72, color: '#fff', weight: 900 }); ctx.restore();
